"""Port 8766. POST /ask, GET /ask/<id>, and one page that shows the steps as they run."""

from __future__ import annotations

import json
from pathlib import Path
import sys
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

from . import ask as ask_module
from . import explain as explain_module
from .store import Store

PORT = 8766
HEADER_PHOTO = Path(__file__).with_name("header.jpg")   # the red rock photo Adam chose, 2026-09-12

STEP_NAMES = [ask_module.STEP_QUESTION, ask_module.STEP_DICTIONARY, ask_module.STEP_PHRASES, ask_module.STEP_NUCLEUS,
              ask_module.STEP_MODEL, ask_module.STEP_GATE, ask_module.STEP_ANSWER]

PAGE = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="nucleus"><meta name="apple-mobile-web-app-status-bar-style" content="default">
<title>nucleus</title>
<style>
:root{--sand:#CDB38B;--lapis:#243F86;--gold:#C59237;--reed:#968C60;--brick:#99292B;--paper:#F7F1E6;--ink:#2A2318;--soft:#5E5443}
body{margin:0;background:var(--sand);color:var(--ink);font-family:-apple-system,Helvetica,Arial,sans-serif;font-size:18px;line-height:1.5}
.page{max-width:760px;margin:0 auto;padding:0 0 60px}
.mast{background:linear-gradient(rgba(36,63,134,.62),rgba(36,63,134,.62)),url(/header.jpg) center 35%/cover no-repeat;color:var(--paper);padding:22px 20px 18px;display:flex;align-items:center;gap:16px;text-shadow:0 1px 3px rgba(0,0,0,.45)}
.mast img.hat{width:64px;height:64px;filter:invert(1) sepia(1) saturate(0) brightness(1.9)}
.mast img.icon{width:44px;height:44px;border-radius:10px;margin-left:auto;box-shadow:0 4px 12px rgba(0,0,0,.3)}
.mast h1{font-family:Georgia,"Times New Roman",serif;font-style:italic;font-weight:400;font-size:34px;margin:0}
.mast .sub{font-size:14px;color:#DCE3F5;margin:2px 0 0}
.body{padding:18px 16px 0}
.ask{background:var(--paper);border:2px solid var(--gold);border-radius:16px;padding:14px 14px 12px;box-shadow:0 10px 26px rgba(40,30,10,.12)}
.ask label{display:block;font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin:0 0 8px}
textarea{width:100%;box-sizing:border-box;font-family:Georgia,"Times New Roman",serif;font-size:21px;line-height:1.45;padding:12px 14px;border:1px solid #DCD4C4;border-radius:10px;background:#fff;color:var(--ink);min-height:120px;resize:none;overflow:hidden}
.row{display:flex;justify-content:space-between;align-items:center;margin-top:10px;gap:10px}
.row .count{font-size:13px;color:var(--soft)}
button.ask-btn{font-size:19px;font-weight:700;padding:14px 26px;border:0;border-radius:12px;background:var(--brick);color:var(--paper);min-height:50px}
button.ask-btn:disabled{opacity:.5}
.steps{display:grid;gap:6px;margin:22px 0 22px}
.step{display:grid;grid-template-columns:1fr 90px;align-items:baseline;padding:9px 14px;border-radius:10px;background:var(--paper);color:#B9AE96;font-size:16px}
.step.running{background:var(--lapis);color:var(--paper)}
.step.done{color:var(--ink)}
.step .t{text-align:right;font-variant-numeric:tabular-nums}
.answer{white-space:pre-wrap;font-size:19px;background:var(--paper);border-radius:16px;padding:18px 16px;margin-top:14px}
.answer:empty{display:none}
.answer .first{font-family:Georgia,"Times New Roman",serif;font-style:italic;font-size:28px;color:var(--brick);margin:0 0 14px}
.answer .first.mm{color:var(--lapis);font-size:22px}
.explain{margin:0 0 18px;padding:14px 16px;background:#fff;border-radius:12px;font-size:20px;line-height:1.45;white-space:pre-wrap}
.explain.pending{color:#7A6E58;font-style:italic;background:none;padding:0 0 10px}
.answer .before{font-family:Georgia,serif;font-style:italic;font-size:18px;color:#7A6E58;margin:0 0 6px}
.more{display:none}
.more.open{display:block}
.reveal{margin-top:14px;font-size:18px;background:none;color:var(--lapis);border:1.5px solid var(--lapis);padding:10px 16px;border-radius:10px}
.stop{color:var(--brick);font-size:20px}
.thumbs{display:inline-flex;gap:8px;margin-left:10px;vertical-align:middle}
.thumbs button{font-size:20px;line-height:1;background:none;border:1.5px solid #CFC5B0;border-radius:10px;padding:6px 10px;color:#7A6E58}
.thumbs button.on.up{background:#2AB860;border-color:#2AB860;color:#fff}
.thumbs button.on.down{background:#B00124;border-color:#B00124;color:#fff}
#recent{margin-top:30px}
#recent .first{font-family:Georgia,serif;font-style:italic;font-size:22px;color:var(--lapis);margin:0 0 6px}
#recent a{display:block;padding:12px 0;border-top:1px solid #B9AE96;color:var(--ink);text-decoration:none}
#recent a b{color:var(--brick)}
</style></head><body><div class="page">
<div class="mast"><img class="hat" src="data:image/png;base64," alt=""><div><h1>nucleus</h1><p class="sub">your words first, then your three answers</p></div><img class="icon" src="data:image/png;base64," alt=""></div>
<div class="body">
<form id="f" class="ask"><label for="q">Your question</label><textarea id="q" placeholder="Write it in your own words. The box grows as you write." autocomplete="off"></textarea>
<div class="row"><span class="count" id="count">0 words</span><button class="ask-btn" id="b" type="submit">Ask</button></div></form>
<div class="steps" id="steps"></div>
<div id="phrases" class="answer"></div>
<div id="answer" class="answer"></div>
<div id="recent"></div>
</div></div>
<script>
const NAMES = __NAMES__;
const FOLD = 4;
const stepsEl = document.getElementById('steps'), answerEl = document.getElementById('answer'), qEl = document.getElementById('q'), countEl = document.getElementById('count');
let current = null, timer = null;
function grow(){ qEl.style.height = 'auto'; qEl.style.height = Math.max(120, qEl.scrollHeight + 4) + 'px'; }
function count(){ const n = (qEl.value.trim().match(/\\S+/g) || []).length; countEl.textContent = n + (n === 1 ? ' word' : ' words'); }
qEl.addEventListener('input', () => { grow(); count(); });
qEl.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey){ e.preventDefault(); document.getElementById('f').requestSubmit(); } });
async function loadRecent(){
  const r = await fetch('/recent'); const rows = await r.json();
  const el = document.getElementById('recent');
  if (!rows.length){ el.innerHTML=''; return; }
  el.innerHTML = '<div class="first">earlier</div>' + rows.map(x => '<a href="#" data-id="'+x.id+'"><b>' + esc(x.answer || x.status) + '</b><br>' + esc(x.question) + '</a>').join('');
  el.querySelectorAll('a').forEach(a => a.onclick = async (e) => { e.preventDefault(); current = a.dataset.id; const r = await fetch('/ask/' + current); const d = await r.json(); qEl.value = d.question.question; grow(); count(); render(d); window.scrollTo(0,0); });
}
loadRecent(); grow(); count();
function render(data){
  stepsEl.innerHTML = '';
  const byName = {};
  (data.steps||[]).forEach(s => byName[s.name] = s);
  const now = Date.now()/1000;
  for (const name of NAMES){
    const s = byName[name];
    const el = document.createElement('div');
    let cls = 'step', t = '';
    if (s){ cls += s.finished ? ' done' : ' running'; t = ((s.finished||now) - s.started).toFixed(1) + ' s'; }
    el.className = cls;
    el.innerHTML = '<span>' + name + '</span><span class="t">' + t + '</span>';
    stepsEl.appendChild(el);
  }
  const ph = data.phrases || [];
  const phEl = document.getElementById('phrases');
  phEl.innerHTML = ph.length ? '<div class="first mm">meaning with meaning</div>' + ph.map(h => '<b>' + esc(h.name) + '</b> — “' + esc(h.text) + '”\\n<span style="color:#7A6E58">“' + esc(h.phrase) + '”</span>').join('\\n\\n') : '';
  const a = data.answer;
  if (!a){ answerEl.innerHTML = ''; return; }
  if (a.status !== 'answered'){ answerEl.innerHTML = '<div class="stop">' + esc(a.status + ': ' + (a.text || a.gate_reason || '')) + '</div>'; return; }
  const lines = (a.text||'').split('\\n');
  const first = lines.shift();
  const blocks = []; let cur = [];
  for (const l of lines){ if (l === '' ) { if (cur.length) blocks.push(cur); cur = []; } else cur.push(l); }
  if (cur.length) blocks.push(cur);
  const shown = blocks.slice(0, FOLD), hidden = blocks.slice(FOLD);
  const before = data.asked_before ? '<div class="before">asked before · ' + data.asked_before + (data.asked_before === 1 ? ' time' : ' times') + '</div>' : '';
  const rows = data.rows || [];
  const block = b => {
    const text = b.join('\\n');
    const row = rows.find(x => x.quote && text.indexOf(x.quote.replace(/\\\\"/g, '"').slice(0, 40)) !== -1);
    if (!row) return esc(text);
    const up = row.thumb === 1 ? ' on' : '', down = row.thumb === 0 ? ' on' : '';
    return esc(text) + '<span class="thumbs" data-word="' + esc(row.word) + '" data-record="' + esc(row.record) + '" data-quote="' + esc(row.quote) + '">'
      + '<button class="up' + up + '" title="keep">👍</button><button class="down' + down + '" title="never again">👎</button></span>';
  };
  // the meaning first. Adam, 2026-09-14: "I don't wanna have to scroll past 60 fucking rows of my words to get down to the goddamn meaning."
  const ex = data.explanation;
  let exHtml = '';
  if (ex && ex.status === 'pending') exHtml = '<div class="explain pending">writing what this says about your question…</div>';
  else if (ex && ex.status === 'shown') {
    const up = ex.thumb === 1 ? ' on' : '', down = ex.thumb === 0 ? ' on' : '';
    exHtml = '<div class="explain">' + esc(ex.text) + '<span class="thumbs" id="exthumbs"><button class="up' + up + '">👍</button><button class="down' + down + '">👎</button></span></div>';
  }
  let html = before + '<div class="first">' + esc(first) + '</div>' + exHtml + shown.map(block).join('\\n\\n');
  if (hidden.length){
    html += '<div class="more" id="more">\\n\\n' + hidden.map(block).join('\\n\\n') + '</div>';
    html += '<button class="reveal" id="reveal">▾ ' + hidden.length + ' more</button>';
  }
  answerEl.innerHTML = html;
  const ext = document.getElementById('exthumbs');
  if (ext) ext.querySelectorAll('button').forEach(b => b.onclick = async () => {
    await fetch('/thumb-explanation', {method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({question_id: current, up: b.classList.contains('up')})});
    ext.querySelectorAll('button').forEach(x => x.classList.remove('on')); b.classList.add('on');
  });
  const r = document.getElementById('reveal');
  if (r) r.onclick = () => { document.getElementById('more').classList.add('open'); r.remove(); };
  answerEl.querySelectorAll('.thumbs button').forEach(b => b.onclick = async () => {
    const t = b.parentElement, up = b.classList.contains('up');
    await fetch('/thumb', {method:'POST', headers:{'content-type':'application/json'},
      body: JSON.stringify({word: t.dataset.word, record: t.dataset.record, quote: t.dataset.quote, up: up})});
    t.querySelectorAll('button').forEach(x => x.classList.remove('on'));
    b.classList.add('on');
  });
}
function esc(s){ return String(s).replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
async function poll(){
  if (!current) return;
  const r = await fetch('/ask/' + current); const data = await r.json();
  render(data);
  if (data.answer && !(data.explanation && data.explanation.status === 'pending')){ clearInterval(timer); timer = null; document.getElementById('b').disabled = false; loadRecent(); }
  else if (data.answer) { document.getElementById('b').disabled = false; }
}
document.getElementById('f').onsubmit = async (e) => {
  e.preventDefault();
  const q = qEl.value.trim(); if (!q) return;
  document.getElementById('b').disabled = true; answerEl.innerHTML = ''; document.getElementById('phrases').innerHTML = '';
  const r = await fetch('/ask', {method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({question:q})});
  const data = await r.json(); current = data.question_id; render({steps:[]});
  timer = setInterval(poll, 500);
};
</script></body></html>
"""


class Handler(BaseHTTPRequestHandler):
    store: Store

    def _json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("content-type", "application/json; charset=utf-8")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:  # noqa: N802
        path = urlparse(self.path).path
        if path == "/":
            body = PAGE.replace("__NAMES__", json.dumps(STEP_NAMES)).replace("__TITLE__", explain_module.TITLE).encode("utf-8")
            self.send_response(200)
            self.send_header("content-type", "text/html; charset=utf-8")
            self.send_header("content-length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        if path == "/header.jpg":
            body = HEADER_PHOTO.read_bytes()
            self.send_response(200)
            self.send_header("content-type", "image/jpeg")
            self.send_header("content-length", str(len(body)))
            self.send_header("cache-control", "max-age=86400")
            self.end_headers()
            self.wfile.write(body)
            return
        if path == "/recent":
            self._json(200, self.store.recent(12))
            return
        if path.startswith("/ask/"):
            question_id = path[len("/ask/"):]
            question = self.store.question(question_id)
            if question is None:
                self._json(404, {"error": "no such question"})
                return
            answer = self.store.answer(question_id)
            self._json(200, {"question": question, "steps": self.store.steps(question_id),
                             "phrases": self.store.phrase_hits(question_id), "answer": answer,
                             "asked_before": self.store.times_asked(question["question"], question_id),
                             "rows": self.store.rows_for_answer((answer or {}).get("reply_json")),
                             "explanation": self.store.explanation(question_id)})
            return
        self._json(404, {"error": "not found"})

    def do_POST(self) -> None:  # noqa: N802
        path = urlparse(self.path).path
        if path not in ("/ask", "/thumb", "/thumb-explanation"):
            self._json(404, {"error": "not found"})
            return
        length = int(self.headers.get("content-length", "0"))
        try:
            payload = json.loads(self.rfile.read(length) or b"{}")
        except json.JSONDecodeError:
            self._json(400, {"error": "the body is not JSON"})
            return
        if path == "/thumb-explanation":
            qid = str(payload.get("question_id", ""))
            if not qid:
                self._json(400, {"error": "question_id"})
                return
            self.store.thumb_explanation(qid, bool(payload.get("up")))
            self._json(200, self.store.explanation(qid) or {})
            return
        if path == "/thumb":
            # his thumb on one link. Up keeps it; down means it never paints again.
            word, record, up = str(payload.get("word", "")), str(payload.get("record", "")), bool(payload.get("up"))
            if not word or not record:
                self._json(400, {"error": "word and record"})
                return
            if self.store.link(word, record) is None:
                self.store.add_link(word, record, str(payload.get("quote", "")), "", "thumb", "adam", "adam")
            self.store.thumb(word, record, up)
            self._json(200, self.store.link(word, record))
            return
        question = str(payload.get("question", "")).strip()
        if not question:
            self._json(400, {"error": "write a question"})
            return
        question_id = self.store.new_question(question, "web")
        thread = threading.Thread(target=self._run, args=(question_id, question), daemon=True)
        thread.start()
        self._json(202, {"question_id": question_id})

    def _run(self, question_id: str, question: str) -> None:
        ask_module.ask(question, store=self.store, surface="web", question_id=question_id)

    def log_message(self, format: str, *args) -> None:  # noqa: A002
        sys.stderr.write("%s %s\n" % (time.strftime("%H:%M:%S"), format % args))


def main() -> None:
    Handler.store = Store()
    server = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)
    print(f"nucleus on http://0.0.0.0:{PORT}/  (this Mac: http://127.0.0.1:{PORT}/, from the phone over Tailscale: http://100.111.154.126:{PORT}/)")
    server.serve_forever()


if __name__ == "__main__":
    main()
